let state=load(),session=JSON.parse(localStorage.portalSession||'null');if(!session?.access_token)state.logged=false;const SB_URL='https://jmsoifzcrvjulzdzyqhr.supabase.co',SB_KEY='eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6Imptc29pZnpjcnZqdWx6ZHp5cWhyIiwicm9sZSI6ImFub24iLCJpYXQiOjE3ODkzMDQxMTQsImV4cCI6MjEwNDg4MDExNH0.vyICz9SQdsr0fr7qCFEEL4Lm-cSfwhQPchbZxTAIqvo';function load(){try{return {...defaults,...JSON.parse(localStorage.portalRumah||'{}')}}catch{return structuredClone(defaults)}} function save(){localStorage.portalRumah=JSON.stringify(state)}
