let pendingRequests=0,fullRequests=0,busyTimer;const syncIndicator=document.createElement('div');syncIndicator.id='syncIndicator';syncIndicator.innerHTML='<i></i><span>Menyinkronkan</span>';document.body.append(syncIndicator);function setBusy(active,full=false){const loader=$('#appLoader');if(active){pendingRequests++;if(full)fullRequests++;if(pendingRequests===1)busyTimer=setTimeout(()=>{if(fullRequests)loader?.classList.add('show');else syncIndicator.classList.add('show')},220);return}pendingRequests=Math.max(0,pendingRequests-1);if(full)fullRequests=Math.max(0,fullRequests-1);if(!pendingRequests){clearTimeout(busyTimer);loader?.classList.remove('show');syncIndicator.classList.remove('show')}}function clearExpiredSession(){session=null;localStorage.removeItem('portalSession');clearFamilyCache();state.logged=false;save()}async function renewSession(){if(!session?.refresh_token)throw new Error('Sesi sudah berakhir. Silakan masuk kembali.');const response=await fetch(`${SB_URL}/auth/v1/token?grant_type=refresh_token`,{method:'POST',headers:{apikey:SB_KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:session.refresh_token})}),text=await response.text();if(!response.ok)throw new Error(JSON.parse(text||'{}').message||'Sesi sudah berakhir. Silakan masuk kembali.');session=JSON.parse(text);localStorage.portalSession=JSON.stringify(session);return session.access_token}async function sb(path,options={}){const {silent=false,...requestOptions}=options,fullScreen=/\/auth\/v1\/(token|signup)/.test(path);if(!silent)setBusy(true,fullScreen);try{let token=session?.access_token||SB_KEY,refreshFailed=false;const request=activeToken=>fetch(SB_URL+path,{...requestOptions,headers:{apikey:SB_KEY,Authorization:`Bearer ${activeToken}`,'Content-Type':'application/json',...(requestOptions.headers||{})}});let res=await request(token);if(res.status===401&&!fullScreen){try{token=await renewSession();res=await request(token)}catch{refreshFailed=true}}if(res.status===401&&refreshFailed){clearExpiredSession();setTimeout(render,0);throw new Error('Sesi sudah berakhir. Silakan masuk kembali.')}const text=await res.text();if(!res.ok)throw new Error(JSON.parse(text||'{}').message||'Koneksi gagal');const data=text?JSON.parse(text):null;return path.includes('/auth/v1/signup')&&data?.access_token?{...data,session:data}:data}finally{if(!silent)setBusy(false,fullScreen)}}
