function logo(){return `<div class="logo"><svg viewBox="0 0 64 64"><path d="M8 27 32 7l24 20M13 24v31h38V24"/><circle cx="24" cy="30" r="7"/><circle cx="41" cy="28" r="6"/><path d="M15 52V43c0-7 5-11 10-11 6 0 7 5 12 5 5 0 6-8 12-8 4 0 6 4 6 8v15"/></svg></div>`}
function status(){return `<div class="status"><b>9:41</b><span>▮▮▮ &nbsp;◉&nbsp; ▰</span></div>`}
function avatar(){return `<button class="avatar" data-action="avatar" aria-label="Ganti foto profil">${state.avatar?`<img src="${state.avatar}" alt="Foto profil">`:'A'}<i>✎</i></button>`}
function bottom(){return `<nav class="bottom"><button data-tab="home" class="${state.tab==='home'?'active':''}">${icons.home}<span>Beranda</span></button><button data-tab="agenda" class="${state.tab==='agenda'?'active':''}">${icons.agenda}<span>Agenda</span></button><button data-tab="history" class="${state.tab==='history'?'active':''}">${icons.history}<span>Riwayat</span></button><button data-tab="profile" class="${state.tab==='profile'?'active':''}">${icons.profile}<span>Profil</span></button></nav>`}
function shell(content,nav=true){return `<div class="app-bg"><section class="phone-app">${status()}<div class="viewport">${content}</div>${nav?bottom():''}</section></div>`}
function login(){const signup=state.authMode==='signup';return shell(`<section class="login"><div class="login-head">${logo()}<h1>${signup?'Buat Akun':'Portal Rumah'}</h1><p>${signup?'Gunakan email aktif untuk keluarga kamu':'Untuk Keluarga yang Lebih Baik'}</p></div><img class="family-art" src="assets/login-interior-coral.png" alt="Keluarga bahagia di ruang keluarga"><form id="${signup?'signupForm':'loginForm'}"><label class="field"><span>✉</span><input name="email" required type="email" placeholder="Email aktif"></label><label class="field"><span>♙</span><input id="password" name="password" required minlength="6" type="password" placeholder="Kata Sandi, minimal 6 karakter"><button type="button" data-action="password">◉</button></label>${signup?`<label class="field"><span>♙</span><input name="confirm" required minlength="6" type="password" placeholder="Ulangi kata sandi"></label><p class="signup-help">Kami akan mengirim tautan konfirmasi ke emailmu.</p>`:`<div class="login-row"><label><input type="checkbox"> Ingat saya</label><button type="button" class="link" data-action="forgot">Lupa kata sandi?</button></div>`}<button class="primary">${signup?'Daftar dan Kirim Konfirmasi':'Masuk'}</button><div class="or"><span>atau</span></div><p>${signup?'Sudah punya akun?':'Belum punya akun?'} <button type="button" class="link" data-auth-mode="${signup?'login':'signup'}">${signup?'Masuk':'Daftar'}</button></p></form></section>`,false)}
const quick=[['agenda','agenda','Agenda'],['money','money','Keuangan'],['health','health','Kesehatan & Anak'],['shop','shop','Belanja'],['archive','archive','Arsip'],['bill','bill','Tagihan'],['quest','quest','Tugas Pasangan'],['map','map','Peta Keluarga'],['chat','health','Chat Keluarga']];
function home(){const pending=state.agenda.filter(x=>!x[3]).length,done=state.agenda.filter(x=>x[3]).length,pct=state.agenda.length?Math.round(done/state.agenda.length*100):0,bell='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';return shell(`<header class="hello"><div><p>Selamat Pagi,</p><h1>Keluarga Andrian</h1><small>Semoga hari ini menyenangkan!</small></div><button class="notice">${bell}<i></i></button>${avatar()}</header><main class="content"><button class="reminder" data-page="agenda"><i>${icons.agenda}</i><span><b>Jangan lupa<br>agenda hari ini!</b><small>${pending} aktivitas menanti</small></span><em>›</em></button><div class="quick">${quick.map(([p,i,l])=>`<button data-page="${p}"><i>${icons[i]}</i><span>${l}</span></button>`).join('')}</div><div class="quote"><i>${icons.home}</i><q>Rumah yang teratur,<br>keluarga yang lebih bahagia</q><b>›</b></div><section class="home-summary"><h2>Ringkasan Rumah</h2><p>Semua dalam kendali, rumah lebih nyaman.</p>${summaryRow('car','Kendaraan Keluarga','Servis 2 hari lagi','car','danger')}${summaryRow('home','Kondisi Rumah','Aman','house')}${summaryRow('shop','Belanja',`${state.shopping.filter(x=>!x[1]).length} item`,'shop')}<div class="weekly"><header><b>Agenda Keluarga</b><strong>${pct}%</strong></header><div class="progress"><i style="width:${pct}%"></i></div>${state.agenda.length?state.agenda.slice(0,5).map((x,i)=>`<label><input type="checkbox" data-list="agenda" data-index="${i}" data-done="3" ${x[3]?'checked':''}><span>${safeText(x[0])}</span></label>`).join(''):'<small>Belum ada agenda keluarga.</small>'}</div></section></main>`) }
function summaryRow(icon,title,sub,page,cls=''){return `<button class="summary-row" data-page="${page}"><i>${icons[icon]}</i><span><b>${title}</b><small class="${cls}">${sub}</small></span><em>›</em></button>`}
const configs={agenda:{title:'Agenda Keluarga',sub:'Atur kegiatan bersama',icon:'agenda',list:'agenda'},money:{title:'Keuangan Rumah',sub:'Pemasukan dan pengeluaran',icon:'money',list:'money'},health:{title:'Kesehatan & Anak',sub:'Catatan kesehatan keluarga',icon:'health',list:'health'},shop:{title:'Daftar Belanja',sub:'Kebutuhan rumah tangga',icon:'shop',list:'shopping'},archive:{title:'Arsip Keluarga',sub:'Dokumen penting tersimpan rapi',icon:'archive',list:'cloudDocs'},bill:{title:'Tagihan Rumah',sub:'Pantau pembayaran bulanan',icon:'bill',list:'bills'},car:{title:'Kendaraan Keluarga',sub:'Pengingat servis dan dokumen',icon:'car',list:'vehicleRecords'},house:{title:'Kondisi Rumah',sub:'Perawatan rumah rutin',icon:'home',list:'homeRecords'},quest:{title:'Tugas Pasangan',sub:'Tugas bersama Ayah dan Ibu',icon:'quest'},map:{title:'Peta Keluarga',sub:'Lokasi penting keluarga',icon:'map'},chat:{title:'Chat Keluarga',sub:'Pesan untuk semua anggota',icon:'health'}};
function displayDate(value){if(!value)return 'Tanggal belum dipilih';const date=new Date(`${value}T00:00:00`);return Number.isNaN(date.getTime())?value:date.toLocaleDateString('id-ID',{day:'numeric',month:'long',year:'numeric'})}
function page(name){if(name==='agenda')return agendaPage();if(name==='shop')return listPage(name,state.shopping,()=> 'Kebutuhan rumah');if(name==='health')return listPage(name,state.health,x=>`Jadwal ${displayDate(x[1])}`);if(name==='bill')return listPage(name,state.bills,x=>`${displayDate(x[1])} · ${idr(x[2])}`);if(name==='money')return moneyPage();if(name==='archive')return archivePage();if(name==='quest')return questPage();if(name==='map')return mapPage();if(name==='chat')return chatPage();if(name==='car'||name==='house')return infoPage(name)}
function header(c){return `<header class="page-head"><button data-action="back">${icons.back}</button><i>${icons[c.icon]}</i><span><h1>${c.title}</h1><p>${c.sub}</p></span></header>`}
function listPage(name,list,meta){const c=configs[name],doneIndex=name==='agenda'?3:name==='health'?2:name==='bill'?3:1;return shell(`${header(c)}<main class="content page-content"><button class="add-card" data-add="${name}">${icons.plus}<span>Tambah ${c.title.split(' ')[0]}</span></button><div class="list">${list.length?list.map((x,i)=>`<article><label class="check"><input type="checkbox" data-list="${c.list}" data-index="${i}" data-done="${doneIndex}" ${x[doneIndex]?'checked':''}><i></i></label><span><b class="${x[doneIndex]?'strike':''}">${x[0]}</b><small>${meta(x)}</small></span><button data-delete="${name}" data-index="${i}">×</button></article>`).join(''):`<div class="empty-state">Belum ada data. Tambahkan data nyata keluarga melalui tombol di atas.</div>`}</div></main>`) }
function monthMatrix(year,monthIndex){const first=new Date(year,monthIndex,1),startDay=first.getDay(),daysInMonth=new Date(year,monthIndex+1,0).getDate(),cells=[];for(let i=0;i<startDay;i++)cells.push(null);for(let d=1;d<=daysInMonth;d++)cells.push(d);while(cells.length%7)cells.push(null);return cells}
function agendaPage(){const now=new Date(),ym=state.calendarMonth||`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,[y,m]=ym.split('-').map(Number),monthName=new Date(y,m-1,1).toLocaleDateString('id-ID',{month:'long',year:'numeric'}),cells=monthMatrix(y,m-1),agenda=state.agenda||[],datesWithAgenda=new Set(agenda.map(x=>x.date).filter(Boolean)),selected=state.calendarSelected,dayNames=['Min','Sen','Sel','Rab','Kam','Jum','Sab'];const grid=`<div class="calendar-card"><header><button type="button" data-cal-nav="-1" aria-label="Bulan sebelumnya">‹</button><b>${monthName}</b><button type="button" data-cal-nav="1" aria-label="Bulan berikutnya">›</button></header><div class="calendar-grid">${dayNames.map(d=>`<span class="cal-dow">${d}</span>`).join('')}${cells.map(d=>{if(!d)return '<span class="cal-empty"></span>';const iso=`${y}-${String(m).padStart(2,'0')}-${String(d).padStart(2,'0')}`,has=datesWithAgenda.has(iso),isSel=selected===iso;return `<button type="button" class="cal-day${has?' has-agenda':''}${isSel?' selected':''}" data-cal-date="${iso}">${d}</button>`}).join('')}</div></div>`;const filtered=selected?agenda.filter(x=>x.date===selected):agenda,listTitle=selected?`Agenda ${displayDate(selected)}`:'Semua Agenda';return shell(`${header(configs.agenda)}<main class="content page-content"><button class="add-card" data-add="agenda">${icons.plus}<span>Tambah Agenda</span></button>${grid}<div class="section-label">${listTitle.toUpperCase()}${selected?' <button type="button" data-cal-clear class="link">Tampilkan semua</button>':''}</div><div class="list">${filtered.length?filtered.map(x=>{const i=agenda.indexOf(x);return `<article><label class="check"><input type="checkbox" data-list="agenda" data-index="${i}" data-done="3" ${x[3]?'checked':''}><i></i></label><span><b class="${x[3]?'strike':''}">${safeText(x[0])}</b><small>${safeText(x[1])} · ${safeText(x[2])}</small></span><button data-delete="agenda" data-index="${i}">×</button></article>`}).join(''):'<div class="empty-state">Belum ada agenda untuk tanggal ini.</div>'}</div></main>`) }
function moneyPage(){const masuk=state.money.filter(x=>x[2]==='masuk').reduce((s,x)=>s+x[1],0),keluar=state.money.filter(x=>x[2]==='keluar').reduce((s,x)=>s+x[1],0);return shell(`${header(configs.money)}<main class="content page-content"><section class="balance"><small>Saldo bulan ini</small><h2>${idr(masuk-keluar)}</h2><div><span>↑ ${idr(masuk)}</span><span>↓ ${idr(keluar)}</span></div></section><button class="add-card" data-add="money">${icons.plus}<span>Tambah Transaksi</span></button><div class="list">${state.money.map((x,i)=>`<article><i class="item-icon">${x[2]==='masuk'?'↑':'↓'}</i><span><b>${x[0]}</b><small class="${x[2]}">${x[2]==='masuk'?'+':'-'} ${idr(x[1])}</small></span><button data-delete="money" data-index="${i}">×</button></article>`).join('')}</div></main>`) }
function archivePage(){const docs=state.cloudDocs||[];return shell(`${header(configs.archive)}<main class="content page-content"><section class="archive-tip"><b>Arsip pribadi keluarga</b><span>Unggah KTP, KK, STNK, sertifikat, bukti bayar, atau dokumen lainnya.</span></section><button class="add-card" data-archive-upload>${icons.plus}<span>Unggah Dokumen</span></button><div class="list">${docs.length?docs.map(x=>`<article class="document-row" data-doc-preview="${x.id}" role="button" tabindex="0"><i class="item-icon">${icons.archive}</i><span><b>${safeText(x.file_name)}</b><small>${safeText(x.category)} · ${Math.max(1,Math.round(x.file_size/1024))} KB · Ketuk untuk preview</small></span><button type="button" aria-label="Preview dokumen">›</button></article>`).join(''):'<div class="empty-state">Belum ada arsip. Tambahkan dokumen penting keluarga di sini.</div>'}</div></main>`) }
function questPage(){const quests=state.cloudTasks||[];return shell(`${header(configs.quest)}<main class="content page-content"><section class="sync-card"><span class="people">I</span><i>↔</i><span class="people">A</span><div><b>${state.family?.name||'Keluarga terhubung'}</b><small>Sinkron otomatis · Kode ${state.family?.invite_code||'-'}</small></div></section><button class="add-card" data-cloud-add>${icons.plus}<span>Kirim tugas baru</span></button><div class="section-label">TUGAS KELUARGA</div><div class="list">${quests.length?quests.map(x=>`<article><label class="check"><input type="checkbox" data-cloud-task="${x.id}" ${x.completed?'checked':''}><i></i></label><span><b class="${x.completed?'strike':''}">${safeText(x.title)}</b><small>${x.completed?'Selesai dan sudah tersinkron':safeText(x.category)+' · menunggu dikerjakan'}</small></span><button data-cloud-delete="${x.id}" aria-label="Hapus tugas">×</button></article>`).join(''):'<div class="empty-state">Belum ada tugas. Tambahkan tugas pertama untuk pasanganmu.</div>'}</div></main>`) }
function mapPage(){const places=(state.places||[]).filter(p=>(p.detail||{}).lat&&(p.detail||{}).lng),mine=places.find(p=>p.created_by===session?.user?.id),rows=places.map(p=>{const d=p.detail||{},mapUrl=`https://www.google.com/maps?q=${d.lat},${d.lng}`;return `<article data-map-focus="${p.id}" role="button" tabindex="0"><i class="item-icon">${icons.map}</i><span><b>${safeText(p.title||'Lokasi keluarga')}</b><small>Diperbarui ${new Date(p.updated_at||p.created_at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}</small></span><a href="${mapUrl}" target="_blank" rel="noopener" onclick="event.stopPropagation()" aria-label="Buka di Google Maps">↗</a></article>`}).join('');return shell(`${header(configs.map)}<main class="content page-content"><section class="family-map"><div id="familyMapCanvas" style="width:100%;height:100%"></div>${places.length?'':'<div class="map-empty-overlay"><span>🗺️</span><b>Belum ada lokasi</b><small>Lokasi anggota keluarga akan muncul di sini.</small></div>'}</section><div class="map-note">Lokasi hanya dibagikan setelah anggota keluarga memberi izin. Peta bisa digeser dan di-zoom seperti Google Maps — ketuk pin buat lihat detail.</div><button class="add-card" data-share-location>${icons.map}<span>${mine?'Perbarui lokasi saya':'Bagikan lokasi saya'}</span></button><div class="list">${places.length?rows:'<div class="empty-state">Belum ada lokasi yang dibagikan. Lokasi akan muncul di sini setelah salah satu anggota memberi izin.</div>'}</div></main>`) }
function safeText(value){return String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}function chatPage(){const messages=state.messages||[],me=session?.user?.id;return shell(`${header(configs.chat)}<main class="content chat-page"><div class="chat-list">${messages.length?messages.map(m=>`<div class="bubble ${m.sender_id===me?'mine':''}"><b>${m.sender_id===me?'Kamu':'Anggota keluarga'}</b><span>${safeText(m.message)}</span><small>${new Date(m.created_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}</small></div>`).join(''):'<div class="empty-state">Belum ada pesan. Mulai percakapan keluarga di sini.</div>'}</div><form id="chatForm" class="chat-form"><input name="message" maxlength="1000" required placeholder="Tulis pesan untuk keluarga"><button>➤</button></form></main>`) }
function infoPage(name){const rows=name==='car'?(state.vehicleRecords||[]):(state.homeRecords||[]),label=name==='car'?'Data kendaraan keluarga':'Catatan kondisi rumah';return shell(`${header(configs[name])}<main class="content page-content"><div class="hero-card"><i>${icons[name==='car'?'car':'home']}</i><span><b>${label}</b><small>${rows.length} catatan tersimpan</small></span></div><button class="add-card" data-add="${name}">${icons.plus}<span>Tambah ${name==='car'?'Kendaraan':'Catatan Rumah'}</span></button><div class="list">${rows.length?rows.map((row,index)=>`<article><i class="item-icon">${icons[name==='car'?'car':'home']}</i><span><b>${safeText(row.title)}</b><small>${safeText((row.detail||{}).note||'Tersimpan untuk keluarga')}</small></span><button data-delete="${name}" data-index="${index}">×</button></article>`).join(''):'<div class="empty-state">Belum ada data nyata. Tambahkan catatan keluarga melalui tombol di atas.</div>'}</div></main>`) }
function history(){return shell(`<header class="simple-head"><h1>Riwayat Aktivitas</h1><p>Semua kegiatan keluarga baru-baru ini.</p></header><main class="content page-content"><div class="list">${[...state.tasks,...state.bills].map(x=>`<article><i class="item-icon">✓</i><span><b>${x[0]}</b><small>Diperbarui hari ini</small></span></article>`).join('')}</div></main>`) }
function profile(){const members=state.members||[],familyName=state.family?.name||'Keluarga Saya',email=session?.user?.email||'Belum ada email';return shell(`<header class="profile-head">${avatar()}<h1>${familyName}</h1><p>${email}</p><button data-action="avatar">Ganti foto profil</button></header><main class="content page-content"><section class="member-panel"><header><b>Anggota Keluarga</b><button data-share-code>＋ Undang</button></header>${members.length?members.map(m=>`<div class="member-row"><i>${m.display_name?.slice(0,1).toUpperCase()||'A'}</i><span><b>${m.display_name}</b><small>${m.role==='owner'?'Pemilik keluarga':'Anggota keluarga'}</small></span></div>`).join(''):'<div class="empty-state">Belum ada anggota. Undang pasangan dengan kode keluarga.</div>'}<small class="invite-code">Kode keluarga: <b>${state.family?.invite_code||'-'}</b></small></section><div class="settings"><button data-enable-push>♢ <span>Notifikasi Push<small>${state.pushEnabled?'Aktif di perangkat ini':'Ketuk untuk aktifkan'}</small></span>›</button><button>⚙ <span>Pengaturan Aplikasi<small>Bahasa Indonesia</small></span>›</button><button class="logout" data-action="logout">↪ <span>Keluar</span></button></div></main>`) }
function onboarding(){return shell(`<section class="onboarding">${logo()}<h1>Hubungkan Keluarga</h1><p>Buat ruang keluarga baru, atau masukkan kode undangan dari pasangan.</p><form id="familyForm"><input name="name" required placeholder="Nama kamu, contoh: Ayah"><input name="family" placeholder="Nama keluarga, contoh: Keluarga Andrian"><button class="primary" name="mode" value="create">Buat Keluarga Baru</button><div class="or"><span>atau</span></div><input name="code" maxlength="8" autocapitalize="characters" placeholder="Kode undangan 8 karakter"><button class="secondary" name="mode" value="join">Gabung dengan Kode</button></form><button class="onboarding-logout" data-action="logout">Keluar / ganti akun</button></section>`,false)}
async function loadFamily(silent=false){const uid=session.user.id,preferred=localStorage.getItem(activeFamilyKey(uid)),select='family_id,display_name,joined_at,families(name,invite_code)',base=`/rest/v1/family_members?select=${select}&user_id=eq.${uid}`;let rows=preferred?await sb(`${base}&family_id=eq.${preferred}&limit=1`,{silent}):[];if(!rows?.length)rows=await sb(`${base}&order=joined_at.desc&limit=1`,{silent});if(!rows?.length){clearFamilyCache();state.onboarding=true;save();return}const row=rows[0],nextFamily={id:row.family_id,name:row.families?.name||'Keluarga',invite_code:row.families?.invite_code||''};if(state.family?.id&&state.family.id!==nextFamily.id)clearFamilyCache();state.onboarding=false;state.family=nextFamily;rememberActiveFamily(nextFamily.id);await Promise.allSettled([loadCloudTasks(silent),loadMembers(silent),loadDocuments(silent),loadDocumentFolders(silent)]);save()}
