function idr(n){return 'Rp'+Number(n).toLocaleString('id-ID')} function render(){let html=!state.logged?login():state.onboarding?onboarding():state.page?page(state.page):state.tab==='home'?home():state.tab==='agenda'?page('agenda'):state.tab==='history'?history():profile();$('#app').innerHTML=html;bind();const loginEmail=$('#loginForm input');if(loginEmail){loginEmail.type='email';loginEmail.placeholder='Email aktif';const loginNote=document.createElement('p');loginNote.className='auth-note';loginNote.textContent='Setelah daftar, cek inbox atau folder Spam untuk mengonfirmasi email.';$('#loginForm').append(loginNote)}}
