document.addEventListener('submit',async event=>{if(event.target.id==='loginForm'){event.preventDefault();event.stopImmediatePropagation();const fields=$$('input',event.target),email=fields[0].value.trim(),password=fields[1].value;try{const result=await sb('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email,password})});session=result;localStorage.portalSession=JSON.stringify(session);clearFamilyCache();state.logged=true;await loadFamily();save();render();toast('Login berhasil')}catch(error){toast(error.message==='Invalid login credentials'?'Email atau password salah':error.message)}}if(event.target.id==='familyForm'){event.preventDefault();const data=new FormData(event.target),mode=event.submitter?.value,name=data.get('name').trim(),familyName=data.get('family').trim()||'Keluarga Kami';try{const result=mode==='create'?await sb('/rest/v1/rpc/create_family',{method:'POST',body:JSON.stringify({family_name:familyName,member_name:name})}):await sb('/rest/v1/rpc/join_family',{method:'POST',body:JSON.stringify({code:data.get('code').trim(),member_name:name})}),joined=result?.[0];if(!joined?.family_id)throw new Error('Keluarga berhasil dibuat, tetapi data keluarga belum diterima. Coba muat ulang.');clearFamilyCache();state.family={id:joined.family_id,name:joined.family_name||familyName,invite_code:joined.invite_code||''};rememberActiveFamily(joined.family_id);state.onboarding=false;save();render();toast(mode==='create'?'Keluarga berhasil dibuat':'Berhasil bergabung dengan keluarga');loadFamily(true).then(()=>{save();render()}).catch(()=>{})}catch(error){toast(error.message)} }},true);
document.addEventListener('click',async event=>{const add=event.target.closest('[data-cloud-add]');if(add){const title=prompt('Tugas apa yang ingin diberikan?')?.trim();if(!title)return;try{const saved=await sb('/rest/v1/family_tasks',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({family_id:state.family.id,title,category:'Tugas Pasangan',created_by:session.user.id})}),task=saved?.[0];if(task)state.cloudTasks=[task,...(state.cloudTasks||[]).filter(item=>item.id!==task.id)];save();render();const notices=await sb('/rest/v1/family_notifications',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({family_id:state.family.id,actor_id:session.user.id,title:'Tugas baru untuk keluarga',body:title})}),notice=notices?.[0];if(notice)await sb('/rest/v1/family_notification_reads?on_conflict=notification_id,user_id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({notification_id:notice.id,user_id:session.user.id})});toast('Tugas terkirim dan notifikasi dibuat');loadCloudTasks(true).then(()=>{save();render()}).catch(()=>{})}catch(error){toast(error.message)}}const remove=event.target.closest('[data-cloud-delete]');if(remove){event.preventDefault();try{await sb(`/rest/v1/family_tasks?id=eq.${remove.dataset.cloudDelete}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});state.cloudTasks=(state.cloudTasks||[]).filter(item=>item.id!==remove.dataset.cloudDelete);save();render();toast('Tugas dihapus untuk seluruh keluarga')}catch(error){toast(/permission|policy|row-level/i.test(error.message)?'Izin hapus tugas belum aktif. Jalankan SQL sinkronisasi terbaru.':error.message)}}if(event.target.closest('[data-action="logout"]')){session=null;localStorage.removeItem('portalSession')}},true);
