document.addEventListener('submit',async event=>{if(event.target.id!=='signupForm')return;event.preventDefault();event.stopImmediatePropagation();const data=new FormData(event.target),email=data.get('email').trim(),password=data.get('password'),confirm=data.get('confirm');if(password!==confirm){toast('Ulangi kata sandi harus sama');return}try{const result=await sb('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password})});state.authMode='login';if(result.session){session=result.session;localStorage.portalSession=JSON.stringify(session);state.logged=true;await loadFamily();render();toast('Akun berhasil dibuat')}else{render();toast('Konfirmasi akun dari emailmu, lalu masuk')}}catch(error){toast(error.message)}},true);
