const archivePicker=document.createElement('input');archivePicker.id='archivePicker';archivePicker.type='file';archivePicker.accept='.pdf,.jpg,.jpeg,.png,.doc,.docx';archivePicker.hidden=true;document.body.appendChild(archivePicker);archivePicker.addEventListener('change',async event=>{const file=event.target.files[0];if(!file||!state.family){toast('Masuk dan buat keluarga terlebih dahulu');return}const category=/ktp/i.test(file.name)?'KTP':/kartu keluarga|\bkk\b/i.test(file.name)?'Kartu Keluarga':/stnk/i.test(file.name)?'STNK':/sertifikat/i.test(file.name)?'Sertifikat':'Dokumen',safeName=file.name.replace(/[^a-zA-Z0-9._-]/g,'_'),path=`${state.family.id}/${crypto.randomUUID()}-${safeName}`,upload=token=>fetch(`${SB_URL}/storage/v1/object/family-documents/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${token}`,'Content-Type':file.type||'application/octet-stream'},body:file});try{let response=await upload(session.access_token);if(response.status===401){await renewSession();response=await upload(session.access_token)}if(!response.ok)throw new Error('Upload dokumen gagal');const saved=await sb('/rest/v1/family_documents',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({family_id:state.family.id,file_name:file.name,file_path:path,category,file_size:file.size,uploaded_by:session.user.id,folder_id:state.archiveFolder||null})}),documentRow=saved?.[0];if(documentRow)state.cloudDocs=[documentRow,...(state.cloudDocs||[]).filter(item=>item.id!==documentRow.id)];save();render();toast('Dokumen tersimpan aman');loadDocuments(true).then(()=>{save();if(state.page==='archive')render()}).catch(()=>{})}catch(error){toast(error.message)}finally{event.target.value=''}});
async function documentBlob(doc){const url=doc.signed_url||await signPrivateFile('family-documents',doc.file_path,3600);doc.signed_url=url;const response=await fetch(url);if(!response.ok)throw new Error('Dokumen tidak dapat dimuat');return {url,blob:await response.blob()}}
async function openDocumentPreview(doc){$('#documentPreview')?.remove();const modal=document.createElement('div');modal.id='documentPreview';modal.className='document-preview';modal.dataset.documentId=doc.id;modal.innerHTML=`<section class="document-preview-card"><header><div><b>${safeText(doc.file_name)}</b><small>${safeText(doc.category||'Dokumen')} · ${Math.max(1,Math.round((doc.file_size||0)/1024))} KB</small></div><button type="button" data-doc-close aria-label="Tutup">×</button></header><div class="document-preview-body"><div class="document-loading"><i></i><span>Menyiapkan preview…</span></div></div><footer><button type="button" class="secondary doc-icon-button danger" data-doc-delete="${safeText(doc.id)}" aria-label="Hapus arsip" title="Hapus">${icons.trash}</button><button type="button" class="secondary" data-doc-share>Bagikan</button><button type="button" class="secondary" data-doc-download>Download</button><button type="button" class="primary" data-doc-full>Buka penuh</button></footer></section>`;document.body.append(modal);const body=$('.document-preview-body',modal);try{const url=await signPrivateFile('family-documents',doc.file_path,3600);doc.signed_url=url;const ext=(doc.file_name.split('.').pop()||'').toLowerCase();body.innerHTML=/^(jpg|jpeg|png|webp|gif)$/.test(ext)?`<img src="${url}" alt="Preview ${safeText(doc.file_name)}">`:ext==='pdf'?`<iframe src="${url}" title="Preview ${safeText(doc.file_name)}"></iframe>`:`<div class="document-no-preview">${icons.archive}<b>Preview tidak tersedia</b><span>Format ${safeText(ext.toUpperCase()||'dokumen')} dapat dibuka penuh atau di-download.</span></div>`}catch(error){body.innerHTML=`<div class="document-no-preview"><b>Dokumen belum dapat ditampilkan</b><span>${safeText(error.message)}</span></div>`}}
