async function downloadFamilyDocument(doc){try{const {blob}=await documentBlob(doc),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=doc.file_name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast('Download dimulai')}catch(error){toast(error.message)}}
