function familyDataFingerprint(){return JSON.stringify({agenda:(state.agenda||[]).map(item=>[item.rid,item[3]]),shopping:(state.shopping||[]).map(item=>[item.rid,item[1]]),health:(state.health||[]).map(item=>[item.rid,item[2]]),bills:(state.bills||[]).map(item=>[item.rid,item[3]]),documents:(state.cloudDocs||[]).map(item=>item.id),tasks:(state.cloudTasks||[]).map(item=>[item.id,item.updated_at]),messages:(state.messages||[]).map(item=>item.id),notifications:(state.notifications||[]).map(item=>[item.id,(item.family_notification_reads||[]).map(read=>read.user_id)]),members:(state.members||[]).map(item=>item.user_id)})}async function syncFamilyData(){if(!state.logged||!state.family||document.hidden)return;const before=familyDataFingerprint(),primary=await Promise.allSettled([loadFamilyBundle(true),loadNotifications(true)]);let results=primary;if(primary[0].status==='rejected')results=primary.concat(await Promise.allSettled([loadRecords(true),loadDocuments(true),loadDocumentFolders(true),loadCloudTasks(true),loadMessages(true),loadMembers(true)]));state.syncFailures=results.filter(result=>result.status==='rejected').length;if(before!==familyDataFingerprint())state.syncDirty=true;const editing=$('#recordModal')||document.activeElement?.closest?.('#chatForm');if(state.syncDirty&&!editing){state.syncDirty=false;save();render()}}setInterval(syncFamilyData,20000);
async function signPrivateFile(bucket,path,expiresIn=86400){const encoded=String(path).split('/').map(encodeURIComponent).join('/'),request=token=>fetch(`${SB_URL}/storage/v1/object/sign/${bucket}/${encoded}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${token}`,'Content-Type':'application/json'},body:JSON.stringify({expiresIn})});let response=await request(session.access_token);if(response.status===401){await renewSession();response=await request(session.access_token)}if(!response.ok)throw new Error('File profil tidak dapat dibuka');const data=await response.json(),signed=data.signedURL||data.signedUrl;if(!signed)throw new Error('Tautan profil tidak tersedia');return signed.startsWith('http')?signed:`${SB_URL}/storage/v1${signed.startsWith('/')?'':'/'}${signed}`}
async function loadProfileAvatar(silent=false){if(!session?.user?.id)return;const rows=await sb(`/rest/v1/user_profiles?select=avatar_path&user_id=eq.${session.user.id}&limit=1`,{silent});if(!rows?.[0]?.avatar_path){state.avatar='';return}state.avatar=await signPrivateFile('family-avatars',rows[0].avatar_path)}
$('#avatarPicker').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(!file.type.startsWith('image/')){toast('Pilih file foto JPG, PNG, atau WebP');e.target.value='';return}if(file.size>5*1024*1024){toast('Ukuran foto maksimal 5 MB');e.target.value='';return}const ext=(file.name.split('.').pop()||'jpg').replace(/[^a-z0-9]/gi,'').toLowerCase(),path=`${session.user.id}/avatar-${Date.now()}.${ext}`;try{let response=await fetch(`${SB_URL}/storage/v1/object/family-avatars/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type},body:file});if(response.status===401){await renewSession();response=await fetch(`${SB_URL}/storage/v1/object/family-avatars/${path}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${session.access_token}`,'Content-Type':file.type},body:file})}if(!response.ok)throw new Error('Upload foto profil gagal');await sb('/rest/v1/user_profiles?on_conflict=user_id',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({user_id:session.user.id,avatar_path:path,updated_at:new Date().toISOString()})});state.avatar=await signPrivateFile('family-avatars',path);save();render();toast('Foto profil tersimpan di semua perangkat')}catch(error){toast(/user_profiles|family-avatars|schema cache/i.test(error.message)?'Penyimpanan foto belum aktif. Jalankan SQL sinkronisasi terbaru.':error.message)}finally{e.target.value=''}};render();

