const originalLoadFamily=loadFamily;loadFamily=async(silent=false)=>{await originalLoadFamily(silent);if(state.family){await Promise.allSettled([loadRecords(silent),loadActivity(silent)]);save()}};
function hydrateFamilyRecords(rows=[]){const pack=(r,a)=>Object.assign(a,{rid:r.id,detail:r.detail||{}});const agendaSortKey=r=>`${(r.detail||{}).date||'9999-99-99'} ${(r.detail||{}).time||'99:99'}`;state.agenda=rows.filter(r=>r.record_type==='agenda').sort((a,b)=>agendaSortKey(a).localeCompare(agendaSortKey(b))).map(r=>{const detail=r.detail||{},date=detail.date?new Date(`${detail.date}T00:00:00`).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}):'';const when=detail.repeat==='daily'?['Setiap hari',detail.time||'--:--'].join(' · '):[date,detail.time||'--:--'].filter(Boolean).join(' · ');return Object.assign([r.title,when,detail.person||'Keluarga',r.completed],{rid:r.id,date:detail.date||'',detail})});state.shopping=rows.filter(r=>r.record_type==='shopping').map(r=>pack(r,[r.title,r.completed]));state.health=rows.filter(r=>r.record_type==='health').map(r=>pack(r,[r.title,(r.detail||{}).date||'Belum dijadwalkan',r.completed]));state.bills=rows.filter(r=>r.record_type==='bill').map(r=>pack(r,[r.title,(r.detail||{}).due||'Belum ditentukan',Number((r.detail||{}).amount)||0,r.completed]));state.vehicleRecords=rows.filter(r=>r.record_type==='vehicle');state.homeRecords=rows.filter(r=>r.record_type==='home');state.places=rows.filter(r=>r.record_type==='place')}
async function loadRecords(silent=false){const rows=await sb(`/rest/v1/family_records?select=*&family_id=eq.${state.family.id}&order=created_at.desc`,{silent});hydrateFamilyRecords(rows)}
async function loadFamilyBundle(silent=false){if(!state.family)return;const bundle=await sb('/rest/v1/rpc/get_family_bundle',{method:'POST',body:JSON.stringify({target_family:String(state.family.id)}),silent});hydrateFamilyRecords(bundle?.records||[]);state.cloudTasks=bundle?.tasks||[];state.messages=bundle?.messages||[];state.cloudDocs=bundle?.documents||[];state.docFolders=bundle?.folders||[];state.members=bundle?.members||[];state.activity=bundle?.activity||[];save()}
async function loadActivity(silent=false){state.activity=await sb(`/rest/v1/family_activity?select=*&family_id=eq.${state.family.id}&order=created_at.desc&limit=30`,{silent})}
async function recordActivity(message){try{await sb('/rest/v1/family_activity',{method:'POST',body:JSON.stringify({family_id:state.family.id,actor_id:session.user.id,message})})}catch{}}
function recordType(name){return ({agenda:'agenda',shop:'shopping',health:'health',bill:'bill',car:'vehicle',house:'home'})[name]}
function openRecordModal(name){const type=recordType(name);if(!type)return;const old=$('#recordModal');if(old)old.remove();const fields={agenda:['Judul agenda','Jam atau tanggal','Penanggung jawab'],shop:['Nama barang','Catatan',''],health:['Kegiatan kesehatan','Tanggal',''],bill:['Nama tagihan','Jatuh tempo','Nominal'],car:['Nama kendaraan','Catatan servis',''],house:['Pemeriksaan rumah','Catatan','']}[name],hasDate=name==='health'||name==='bill';const firstField=hasDate?`<label class="calendar-field">${fields[1]}<input required type="date" name="one"></label>`:`<input name="one" placeholder="${fields[1]}">`,secondField=fields[2]?`<input name="two" ${name==='bill'?'type="number" inputmode="numeric" min="0"':''} placeholder="${fields[2]}">`:'';const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Tambah ${configs[name].title}</b><button type="button" data-close-modal>×</button></header><input required name="title" placeholder="${fields[0]}">${firstField}${secondField}<button class="primary">Simpan</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),detail=type==='agenda'?{time:d.get('one'),person:d.get('two')}:type==='health'?{date:d.get('one')}:type==='bill'?{due:d.get('one'),amount:Number(d.get('two'))||0}:{note:d.get('one')};try{await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:type,title:d.get('title').trim(),detail,created_by:session.user.id})});await loadRecords();await recordActivity(`Menambahkan ${d.get('title').trim()}`);modal.remove();render();toast('Data keluarga tersimpan')}catch(error){toast(error.message)}}}
document.addEventListener('click',e=>{const addButton=e.target.closest('[data-add]');if(addButton){e.preventDefault();e.stopImmediatePropagation();openRecordModal(addButton.dataset.add)}if(e.target.closest('[data-close-modal]'))$('#recordModal')?.remove()},true);
document.addEventListener('change',async e=>{const box=e.target.closest('[data-list]');if(!box||!state.family)return;const arr=state[box.dataset.list],item=arr?.[Number(box.dataset.index)],rid=item?.rid;if(!rid)return;e.stopImmediatePropagation();const reason=!box.checked?prompt('Kenapa belum selesai? Isi alasan singkat supaya masuk Riwayat.')?.trim():'';if(!box.checked&&!reason){box.checked=true;toast('Alasan wajib diisi kalau belum selesai');return}const detail={...(item.detail||{})};if(box.checked&&detail.repeat==='daily')detail.completed_on=todayIso();if(!box.checked){detail.incomplete_reason=reason;if(detail.repeat==='daily')delete detail.completed_on}else delete detail.incomplete_reason;try{await sb(`/rest/v1/family_records?id=eq.${rid}`,{method:'PATCH',body:JSON.stringify({completed:box.checked,completed_by:box.checked?session.user.id:null,completed_at:box.checked?new Date().toISOString():null,detail,updated_at:new Date().toISOString()})});await loadRecords();await recordActivity(`${item[0]} ditandai ${box.checked?'selesai':'belum selesai'}`);render()}catch(error){toast(error.message)}},true);
document.addEventListener('click',async e=>{const del=e.target.closest('[data-delete]');if(!del||!state.family)return;const key=configs[del.dataset.delete]?.list,arr=state[key],index=Number(del.dataset.index),item=arr?.[index],recordId=item?.rid||item?.id,title=item?.[0]||item?.title;if(!recordId)return;e.preventDefault();e.stopImmediatePropagation();try{await sb(`/rest/v1/family_records?id=eq.${recordId}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});arr.splice(index,1);save();render();toast('Data dihapus');recordActivity(`Menghapus ${title}`);loadRecords(true).then(()=>{save();render()}).catch(()=>{})}catch(error){toast(/permission|policy|row-level/i.test(error.message)?'Izin hapus belum aktif. Jalankan SQL sinkronisasi terbaru.':error.message)}},true);
const baseRender=render;render=()=>{const oldView=$('.viewport'),scrollTop=oldView?.scrollTop||0;baseRender();const view=$('.viewport');if(view)requestAnimationFrame(()=>{view.scrollTop=scrollTop});const greeting=$('.hello h1');if(greeting){greeting.textContent=state.family?.name||'Keluarga Saya';const header=$('.hello');if(header&&!header.querySelector('.home-brand'))header.querySelector('div').insertAdjacentHTML('afterbegin',`<div class="home-brand">${logo()}<span>PORTAL RUMAH</span></div>`)}const rows=$$('.summary-row');if(rows){if(!state.vehicleRecords?.length)rows[0]?.querySelector('small')&&(rows[0].querySelector('small').textContent='Belum diisi');if(!state.homeRecords?.length)rows[1]?.querySelector('small')&&(rows[1].querySelector('small').textContent='Belum diisi')};};
