// --- Detail belanja, checklist harian yang tetap terlihat, dan sapaan sesuai waktu ---
function timeGreeting(){const hour=new Date().getHours();if(hour>=4&&hour<11)return 'Selamat Pagi,';if(hour>=11&&hour<15)return 'Selamat Siang,';if(hour>=15&&hour<18)return 'Selamat Sore,';return 'Selamat Malam,'}
const agendaStatusBeforeDailyVisible=agendaStatus;
agendaStatus=function(item){const detail=item.detail||{},diff=isoDaysFromNow(item.date),isToday=detail.repeat==='daily'||diff===0,isMissed=diff<0&&!item[3];if(item[3]&&isToday)return 'today';if(item[3])return 'done';if(isMissed)return 'missed';return agendaStatusBeforeDailyVisible(item)};
const checklistItemsBeforeDailyVisible=checklistItems;
checklistItems=function(){const items=(state.agenda||[]).map((item,index)=>({item,index,status:agendaStatus(item)}));const filter=state.homeChecklistFilter||'today';if(filter==='today')return items.filter(entry=>['today','missed'].includes(entry.status));if(filter==='upcoming')return items.filter(entry=>entry.status==='upcoming'&&!entry.item[3]);if(filter==='done')return items.filter(entry=>entry.item[3]);return items};
const hydrateRecordsBeforeDailyVisible=hydrateFamilyRecords;
hydrateFamilyRecords=function(rows=[]){hydrateRecordsBeforeDailyVisible(rows);state.agenda=(state.agenda||[]).map(item=>{if(item.detail?.repeat==='daily')item[3]=item.detail.completed_on===todayIso();return item});state.shopping=(state.shopping||[]).map(item=>Object.assign(item,{detail:item.detail||{}}))};
function shoppingMeta(item){const parts=[];if(item.detail?.qty)parts.push(item.detail.qty);if(item.detail?.note)parts.push(item.detail.note);return parts.length?parts.join(' · '):'Ketuk untuk lihat catatan'}
function shoppingPage(){const list=state.shopping||[];return shell(`${header(configs.shop)}<main class="content page-content"><button class="add-card" data-add="shop">${icons.plus}<span>Tambah Belanja</span></button><div class="list shopping-list">${list.length?list.map((x,i)=>`<article><label class="check"><input type="checkbox" data-list="shopping" data-index="${i}" data-done="1" ${x[1]?'checked':''}><i></i></label><button type="button" class="shopping-detail-trigger" data-shop-detail="${i}"><span><b class="${x[1]?'strike':''}">${safeText(x[0])}</b><small>${safeText(shoppingMeta(x))}</small></span><em>›</em></button><button data-delete="shop" data-index="${i}">×</button></article>`).join(''):`<div class="empty-state">Belum ada daftar belanja. Tambahkan kebutuhan rumah melalui tombol di atas.</div>`}</div></main>`) }
function openShoppingModal(){const old=$('#recordModal');if(old)old.remove();const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Tambah Belanja</b><button type="button" data-close-modal>×</button></header><input required name="title" placeholder="Nama belanja, contoh: Obat"><input name="qty" placeholder="Jumlah/rincian, contoh: Paracetamol 2 strip"><textarea name="note" rows="3" placeholder="Catatan lengkap, contoh: beli yang tablet, untuk demam anak"></textarea><button class="primary">Simpan Belanja</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),title=d.get('title').trim(),detail={qty:d.get('qty').trim(),note:d.get('note').trim()};try{await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:'shopping',title,detail,created_by:session.user.id})});await loadRecords();await recordActivity(`Menambahkan belanja ${title}`);modal.remove();render();toast('Belanja tersimpan')}catch(error){toast(error.message)}}}
function openShoppingDetail(item){$('#recordModal')?.remove();const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<section class="record-card shopping-detail-card"><header><b>${safeText(item[0])}</b><button type="button" data-close-modal>×</button></header><div class="detail-line"><span>Jumlah/Rincian</span><b>${safeText(item.detail?.qty||'-')}</b></div><div class="detail-line"><span>Catatan</span><p>${safeText(item.detail?.note||'Belum ada catatan tambahan.')}</p></div><button type="button" class="primary" data-close-modal>Tutup</button></section>`;document.body.append(modal)}
