const motionFix=document.createElement('style');motionFix.textContent='.loader-mark{position:relative}.phone-app,.viewport>*,.quick button,.summary-row,.list article,.settings button{animation:none!important}#syncIndicator{position:fixed;z-index:190;left:50%;top:max(18px,env(safe-area-inset-top));display:flex;align-items:center;gap:7px;padding:8px 12px;border-radius:999px;background:rgba(54,12,20,.82);color:#fff;font:600 11px "DM Sans",sans-serif;box-shadow:0 8px 22px rgba(54,12,20,.2);opacity:0;transform:translate(-50%,-10px);pointer-events:none;transition:opacity .18s ease,transform .18s ease}#syncIndicator.show{opacity:1;transform:translate(-50%,0)}#syncIndicator i{width:13px;height:13px;border:2px solid rgba(255,255,255,.35);border-top-color:#fff;border-radius:50%;animation:loader-spin .7s linear infinite}.onboarding-logout{margin-top:16px;border:0;background:transparent;color:#9e1730;font-weight:700;font-size:12px}';document.head.append(motionFix);
const genericRecordModal=openRecordModal;openRecordModal=name=>{if(name!=='agenda')return genericRecordModal(name);const old=$('#recordModal');if(old)old.remove();const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Tambah Agenda</b><button type="button" data-close-modal>×</button></header><input required name="title" placeholder="Judul agenda"><label class="calendar-field">Tanggal<input required type="date" name="date"></label><label class="calendar-field">Waktu<input type="time" name="time"></label><button class="primary">Simpan Agenda</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),title=d.get('title').trim(),date=d.get('date'),time=d.get('time')||'--:--';try{await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:'agenda',title,detail:{date,time,person:'Keluarga'},created_by:session.user.id})});await loadRecords();await recordActivity(`Menambahkan agenda ${title}`);modal.remove();render();toast('Agenda tersimpan')}catch(error){toast(error.message)}}};
async function loadNotifications(silent=false){if(!state.family)return;state.notifications=await sb(`/rest/v1/family_notifications?select=*,family_notification_reads(user_id)&family_id=eq.${state.family.id}&order=created_at.desc&limit=20`,{silent})}
function isUnreadNotification(note){return !(note.family_notification_reads||[]).some(read=>read.user_id===session?.user?.id)}
async function markNotificationsRead(){if(!session?.user?.id)return;const unread=(state.notifications||[]).filter(isUnreadNotification);if(!unread.length)return;const uid=session.user.id;unread.forEach(note=>note.family_notification_reads=[...(note.family_notification_reads||[]),{user_id:uid}]);save();render();try{await sb('/rest/v1/family_notification_reads?on_conflict=notification_id,user_id',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify(unread.map(note=>({notification_id:note.id,user_id:uid})))})}catch(error){unread.forEach(note=>note.family_notification_reads=(note.family_notification_reads||[]).filter(read=>read.user_id!==uid));save();render();toast(/family_notification_reads|schema cache/i.test(error.message)?'Status baca belum aktif. Jalankan SQL sinkronisasi terbaru.':error.message)}}
async function loadMessages(silent=false){if(!state.family)return;state.messages=await sb(`/rest/v1/family_messages?select=*&family_id=eq.${state.family.id}&order=created_at.asc&limit=100`,{silent})}
const familyLoaderWithChat=loadFamily;loadFamily=async(silent=false)=>{await familyLoaderWithChat(silent);if(state.family){await Promise.allSettled([loadFamilyBundle(silent),loadNotifications(silent),loadProfileAvatar(silent)]);save()}};
document.addEventListener('submit',async event=>{if(event.target.id!=='chatForm')return;event.preventDefault();const input=$('input',event.target),message=input.value.trim(),submitter=$('button',event.target);if(!message)return;if(submitter)submitter.disabled=true;try{const saved=await sb('/rest/v1/family_messages',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({family_id:state.family.id,sender_id:session.user.id,message})}),messageRow=saved?.[0];input.value='';if(messageRow)state.messages=[...(state.messages||[]).filter(item=>item.id!==messageRow.id),messageRow];save();render();loadMessages(true).then(()=>{save();if(state.page==='chat')render()}).catch(()=>{})}catch(error){toast(/family_messages|schema cache/i.test(error.message)?'Chat belum aktif. Jalankan SQL perbaikan chat terlebih dahulu.':error.message)}finally{if(submitter)submitter.disabled=false}},true);

function notificationPage(){const notes=state.notifications||[];return shell(`${header({title:'Notifikasi',sub:'Tugas dan kabar keluarga',icon:'agenda'})}<main class="content notification-page">${notes.length?`<div class="notification-list">${notes.map(note=>`<article class="notification-card${isUnreadNotification(note)?' unread':''}"><i>${icons.agenda}</i><div><b>${safeText(note.title)}</b><p>${safeText(note.body||'')}</p><small>${new Date(note.created_at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}</small></div></article>`).join('')}</div>`:'<div class="empty-state">Belum ada notifikasi keluarga.</div>'}</main>`) }
const standardPage=page;page=name=>name==='notifications'?notificationPage():standardPage(name);
const renderWithNotifications=render;render=()=>{renderWithNotifications();const notice=$('.notice');if(notice){notice.type='button';notice.setAttribute('aria-label','Buka notifikasi');notice.onclick=()=>{state.page='notifications';render();markNotificationsRead()};const dot=notice.querySelector('i');if(dot)dot.style.display=(state.notifications||[]).some(isUnreadNotification)?'block':'none'}};
