async function shareCurrentLocation(){if(!state.family||!session?.user){toast('Masuk dan buat keluarga terlebih dahulu');return}if(!navigator.geolocation){toast('Perangkat ini belum mendukung lokasi');return}toast('Meminta izin lokasi…');navigator.geolocation.getCurrentPosition(async position=>{const lat=Number(position.coords.latitude.toFixed(6)),lng=Number(position.coords.longitude.toFixed(6)),member=state.members?.find(item=>item.user_id===session.user.id),title=`Lokasi ${member?.display_name||'saya'}`,detail={lat,lng,accuracy:Math.round(position.coords.accuracy)};try{const existing=(state.places||[]).find(item=>item.created_by===session.user.id);if(existing)await sb(`/rest/v1/family_records?id=eq.${existing.id}`,{method:'PATCH',body:JSON.stringify({title,detail,updated_at:new Date().toISOString()})});else await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:'place',title,detail,created_by:session.user.id})});await loadRecords();await recordActivity('Memperbarui lokasi keluarga');render();toast('Lokasi berhasil dibagikan')}catch(error){toast(error.message)}},error=>toast(error.code===1?'Izin lokasi belum diberikan':'Lokasi tidak dapat ditemukan'),{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
document.addEventListener('click',event=>{if(event.target.closest('[data-share-location]')){event.preventDefault();shareCurrentLocation()}},true);
async function copyInviteCode(){const code=state.family?.invite_code;if(!code){toast('Kode undangan belum tersedia');return}try{if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(code);else{const helper=document.createElement('textarea');helper.value=code;helper.style.position='fixed';helper.style.opacity='0';document.body.append(helper);helper.select();document.execCommand('copy');helper.remove()}toast(`Kode ${code} sudah disalin. Kirim ke pasanganmu.`)}catch{toast(`Kode undangan: ${code}`)}}
document.addEventListener('click',event=>{if(event.target.closest('[data-share-code]')){event.preventDefault();copyInviteCode()}},true);
document.addEventListener('click',event=>{const nav=event.target.closest('[data-cal-nav]');if(nav){event.preventDefault();const now=new Date(),[y,m]=(state.calendarMonth||`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`).split('-').map(Number),d=new Date(y,m-1+Number(nav.dataset.calNav),1);state.calendarMonth=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;save();render();return}const dayBtn=event.target.closest('[data-cal-date]');if(dayBtn){event.preventDefault();state.calendarSelected=state.calendarSelected===dayBtn.dataset.calDate?null:dayBtn.dataset.calDate;save();render();return}if(event.target.closest('[data-cal-clear]')){event.preventDefault();state.calendarSelected=null;save();render()}},true);
// --- Notifikasi push: minta izin lalu simpan langganan push milik perangkat ini ---
const VAPID_PUBLIC_KEY='BA9C0Ba3Pw8QIdWq1V7bIEwrhc5wVfwWgZUe7Do2X1FpE7yshExQPZCFhi21IwrzdvOe_4F6koBzppr-_UJN-Wk';
function urlBase64ToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4),base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/'),raw=atob(base64),output=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)output[i]=raw.charCodeAt(i);return output}
async function enablePushNotifications(){if(!('serviceWorker' in navigator)||!('PushManager' in window)){toast('Perangkat/browser ini belum mendukung notifikasi push');return}if(!state.family){toast('Masuk dan buat keluarga terlebih dahulu');return}try{const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Izin notifikasi ditolak');return}const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:urlBase64ToUint8Array(VAPID_PUBLIC_KEY)});const json=subscription.toJSON();await sb('/rest/v1/push_subscriptions?on_conflict=endpoint',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({family_id:state.family.id,user_id:session.user.id,endpoint:json.endpoint,p256dh:json.keys.p256dh,auth_key:json.keys.auth})});state.pushEnabled=true;save();render();toast('Notifikasi keluarga aktif di perangkat ini')}catch(error){toast(/push_subscriptions|schema cache/i.test(error.message)?'Notifikasi push belum aktif. Jalankan SQL setup push terlebih dahulu.':(error.message||'Gagal mengaktifkan notifikasi'))}}
document.addEventListener('click',event=>{if(event.target.closest('[data-enable-push]')){event.preventDefault();enablePushNotifications()}},true);
function applyPushLaunchRoute(){const requested=new URL(location.href).searchParams.get('open');if(!requested||!state.logged||!state.family)return false;const allowed={chat:'chat',agenda:'agenda',quest:'quest'};if(!allowed[requested])return false;state.tab=requested==='agenda'?'agenda':'home';state.page=requested==='agenda'?null:allowed[requested];history.replaceState({},'',location.pathname);return true}
async function restoreFamilySession(){if(!session?.access_token||!state.logged)return;try{await loadFamily(true);applyPushLaunchRoute();save();render()}catch(error){if(/sesi|jwt|unauthorized/i.test(error.message)){clearExpiredSession();render()}else toast('Data keluarga belum dapat dimuat')}}
// --- Realtime: dorong perubahan antar anggota keluarga secara instan ---
// Dipakai bersama syncFamilyData() (polling) sebagai jaring pengaman kalau
// koneksi websocket realtime putus (mis. jaringan seluler tidak stabil).
let realtimeChannel=null,realtimeFamilyId=null,realtimeDebounceTimer=null;
function realtimeDebounce(){clearTimeout(realtimeDebounceTimer);realtimeDebounceTimer=setTimeout(async()=>{if(!state.family)return;await Promise.allSettled([loadFamilyBundle(true),loadNotifications(true)]);const editing=$('#recordModal')||document.activeElement?.closest?.('#chatForm');if(!editing){save();render()}else state.syncDirty=true},200)}
function subscribeRealtime(familyId){if(!window.supabase||!familyId||familyId===realtimeFamilyId)return;unsubscribeRealtime();realtimeFamilyId=familyId;if(!window.supabaseClient)window.supabaseClient=window.supabase.createClient(SB_URL,SB_KEY,{auth:{persistSession:false}});window.supabaseClient.realtime.setAuth(session?.access_token);const tables=['family_records','family_documents','family_document_folders','family_tasks','family_messages','family_notifications','family_activity','family_members'];const channel=window.supabaseClient.channel(`family-${familyId}`);tables.forEach(table=>channel.on('postgres_changes',{event:'*',schema:'public',table,filter:`family_id=eq.${familyId}`},realtimeDebounce));channel.subscribe(status=>{if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')console.warn('[realtime] channel keluarga gagal tersambung, memakai polling cadangan')});realtimeChannel=channel}
function unsubscribeRealtime(){if(realtimeChannel&&window.supabaseClient)window.supabaseClient.removeChannel(realtimeChannel);realtimeChannel=null;realtimeFamilyId=null}
const clearFamilyCacheWithRealtime=clearFamilyCache;clearFamilyCache=function(){unsubscribeRealtime();clearFamilyCacheWithRealtime()};
const renewSessionWithRealtime=renewSession;renewSession=async function(){const token=await renewSessionWithRealtime();if(window.supabaseClient)window.supabaseClient.realtime.setAuth(token);return token};
const loadFamilyWithRealtime=loadFamily;loadFamily=async(silent=false)=>{await loadFamilyWithRealtime(silent);if(state.family)subscribeRealtime(state.family.id)};
document.addEventListener('visibilitychange',()=>{if(!document.hidden){applyPushLaunchRoute();syncFamilyData()}});window.addEventListener('pageshow',()=>{if(applyPushLaunchRoute())render();syncFamilyData()});restoreFamilySession();

// --- Penyempurnaan navigasi: Agenda di shortcut diganti Darurat, kalender tetap di bottom bar ---
icons.emergency=svg('<path d="M12 21s7-4.4 7-11a7 7 0 1 0-14 0c0 6.6 7 11 7 11Z"/><path d="M12 7v6m-3-3h6"/>');
icons.glasses=svg('<circle cx="8" cy="14" r="3.5"/><circle cx="16" cy="14" r="3.5"/><path d="M11.5 14h1M4.5 13l-1.5-2m16.5 2 1.5-2"/>');
icons.pencil=svg('<path d="M4 20h4l11-11a2.8 2.8 0 0 0-4-4L4 16v4Z"/><path d="m13.5 6.5 4 4"/>');
icons.folder=svg('<path d="M3 7a2 2 0 0 1 2-2h4l2 2h8a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2Z"/>');
icons.trash=svg('<path d="M4 7h16M9 7V5a2 2 0 0 1 2-2h2a2 2 0 0 1 2 2v2m-9 0 1 13a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2l1-13"/><path d="M10 11v6m4-6v6"/>');
configs.agenda.title='Kalender Keluarga';
configs.agenda.sub='Semua jadwal dan rutinitas keluarga';
configs.emergency={title:'Kontak Darurat',sub:'Nomor penting keluarga',icon:'emergency',list:'emergencyRecords'};
quick[0]=['emergency','emergency','Darurat'];
state.lang=state.lang||'id';
state.homeChecklistFilter=state.homeChecklistFilter||'today';

function todayIso(){return new Date().toISOString().slice(0,10)}
function isoDaysFromNow(value){if(!value)return Infinity;const start=new Date(`${todayIso()}T00:00:00`),target=new Date(`${value}T00:00:00`);return Math.round((target-start)/86400000)}
function agendaStatus(item){const detail=item.detail||{};if(item[3])return 'done';if(detail.repeat==='daily')return 'today';const diff=isoDaysFromNow(item.date);if(diff===0)return 'today';if(diff>0&&diff<=7)return 'upcoming';if(diff<0)return 'missed';return 'all'}
function checklistItems(){const items=(state.agenda||[]).map((item,index)=>({item,index,status:agendaStatus(item)}));const filter=state.homeChecklistFilter||'today';if(filter==='today')return items.filter(entry=>['today','missed'].includes(entry.status)&&!entry.item[3]);if(filter==='upcoming')return items.filter(entry=>entry.status==='upcoming'&&!entry.item[3]);if(filter==='done')return items.filter(entry=>entry.item[3]);return items}
function checklistFilterButton(key,label){return `<button type="button" data-checklist-filter="${key}" class="${state.homeChecklistFilter===key?'active':''}">${label}</button>`}
function home(){const entries=checklistItems(),agenda=state.agenda||[],todayScope=agenda.filter(x=>['today','missed'].includes(agendaStatus(x))),done=todayScope.filter(x=>x[3]).length,pct=todayScope.length?Math.round(done/todayScope.length*100):0,pendingToday=todayScope.filter(x=>!x[3]).length,bell='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 9a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"/></svg>';return shell(`<header class="hello"><div><p>Selamat Pagi,</p><h1>Keluarga Andrian</h1><small>Semoga hari ini menyenangkan!</small></div><button class="notice">${bell}<i></i></button>${avatar()}</header><main class="content"><button class="reminder" data-tab="agenda"><i>${icons.agenda}</i><span><b>Hari ini<br>perlu dicek</b><small>${pendingToday} aktivitas menanti</small></span><em>›</em></button><div class="quick">${quick.map(([p,i,l])=>`<button data-page="${p}"><i>${icons[i]}</i><span>${l}</span></button>`).join('')}</div><div class="quote"><i>${icons.home}</i><q>Rumah yang teratur,<br>keluarga yang lebih bahagia</q><b>›</b></div><section class="home-summary"><h2>Ringkasan Rumah</h2><p>Semua dalam kendali, rumah lebih nyaman.</p>${summaryRow('car','Kendaraan Keluarga','Servis 2 hari lagi','car','danger')}${summaryRow('home','Kondisi Rumah','Aman','house')}${summaryRow('shop','Belanja',`${state.shopping.filter(x=>!x[1]).length} item`,'shop')}<div class="weekly checklist-today"><header><b>Checklist Hari Ini</b><strong>${pct}%</strong></header><div class="progress"><i style="width:${pct}%"></i></div><div class="filter-chips">${checklistFilterButton('today','Hari ini')}${checklistFilterButton('upcoming','Mendatang')}${checklistFilterButton('all','Semua')}${checklistFilterButton('done','Selesai')}</div>${entries.length?entries.slice(0,7).map(({item,index,status})=>`<label class="${status==='missed'?'missed':''}"><input type="checkbox" data-list="agenda" data-index="${index}" data-done="3" ${item[3]?'checked':''}><span>${safeText(item[0])}<small>${safeText(item[1]||'Rutinitas')} ${status==='missed'?'· terlewat':''}</small></span></label>`).join(''):'<small>Belum ada aktivitas untuk filter ini.</small>'}</div></section></main>`) }
const pageBeforeEmergency=page;
page=name=>name==='emergency'?emergencyPage():pageBeforeEmergency(name);

function emergencyPage(){const rows=state.emergencyRecords||[];return shell(`${header(configs.emergency)}<main class="content page-content"><section class="archive-tip emergency-tip"><b>Siap saat dibutuhkan</b><span>Simpan RS, dokter, satpam, tetangga, sekolah, PLN, PDAM, bengkel, ambulans, polisi, atau damkar.</span></section><button class="add-card" data-add="emergency">${icons.plus}<span>Tambah Kontak</span></button><div class="list emergency-list">${rows.length?rows.map((row,index)=>{const detail=row.detail||{},phone=detail.phone||'',category=detail.category||'Darurat';return `<article><i class="item-icon">${icons.emergency}</i><span><b>${safeText(row.title)}</b><small>${safeText(category)}${phone?' · '+safeText(phone):''}${detail.note?' · '+safeText(detail.note):''}</small></span>${phone?`<a class="call-button" href="tel:${safeText(phone)}" aria-label="Telepon ${safeText(row.title)}">Telp</a>`:''}<button data-delete="emergency" data-index="${index}">×</button></article>`}).join(''):'<div class="empty-state">Belum ada kontak darurat. Tambahkan nomor penting keluarga di sini.</div>'}</div></main>`) }

const hydrateRecordsBeforeEmergency=hydrateFamilyRecords;
hydrateFamilyRecords=function(rows=[]){hydrateRecordsBeforeEmergency(rows);state.emergencyRecords=rows.filter(r=>r.record_type==='emergency')};
const recordTypeBeforeEmergency=recordType;
recordType=name=>name==='emergency'?'emergency':recordTypeBeforeEmergency(name);
const openRecordModalBeforeEmergency=openRecordModal;
openRecordModal=function(name){if(name==='emergency')return openEmergencyModal();if(name==='agenda')return openAgendaModal();return openRecordModalBeforeEmergency(name)};

function openEmergencyModal(){const old=$('#recordModal');if(old)old.remove();const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Tambah Kontak Darurat</b><button type="button" data-close-modal>×</button></header><input required name="title" placeholder="Nama kontak, contoh: RS terdekat"><input required name="phone" inputmode="tel" placeholder="Nomor telepon"><select name="category"><option>Rumah Sakit</option><option>Dokter</option><option>Sekolah</option><option>Keamanan</option><option>Tetangga</option><option>PLN / PDAM</option><option>Bengkel</option><option>Lainnya</option></select><input name="note" placeholder="Catatan singkat, contoh: terima BPJS"><button class="primary">Simpan Kontak</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),title=d.get('title').trim(),detail={phone:d.get('phone').trim(),category:d.get('category'),note:d.get('note').trim()};try{await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:'emergency',title,detail,created_by:session.user.id})});await loadRecords();await recordActivity(`Menambahkan kontak darurat ${title}`);modal.remove();render();toast('Kontak darurat tersimpan')}catch(error){toast(error.message)}}}
function openAgendaModal(){const old=$('#recordModal');if(old)old.remove();const modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Tambah Agenda</b><button type="button" data-close-modal>×</button></header><input required name="title" placeholder="Judul agenda atau rutinitas"><select name="repeat"><option value="">Agenda tanggal tertentu</option><option value="daily">Rutinitas harian</option></select><label class="calendar-field">Tanggal<input type="date" name="date"></label><label class="calendar-field">Waktu<input type="time" name="time"></label><input name="person" placeholder="Penanggung jawab, contoh: Ayah"><button class="primary">Simpan Agenda</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),title=d.get('title').trim(),repeat=d.get('repeat'),date=d.get('date'),time=d.get('time')||'--:--';if(!repeat&&!date){toast('Pilih tanggal agenda atau jadikan rutinitas harian');return}try{await sb('/rest/v1/family_records',{method:'POST',body:JSON.stringify({family_id:state.family.id,record_type:'agenda',title,detail:{date,repeat,time,person:d.get('person').trim()||'Keluarga'},created_by:session.user.id})});await loadRecords();await recordActivity(`Menambahkan agenda ${title}`);modal.remove();render();toast(repeat==='daily'?'Rutinitas harian tersimpan':'Agenda tersimpan')}catch(error){toast(error.message)}}}

function history(){const agendaItems=(state.agenda||[]).map(item=>({title:item[0],meta:item[1],done:item[3],reason:item.detail?.incomplete_reason,type:'Agenda'})),taskItems=(state.cloudTasks||[]).map(item=>({title:item.title,meta:item.category||'Tugas pasangan',done:item.completed,reason:item.reason||'',type:'Tugas'})),billItems=(state.bills||[]).map(item=>({title:item[0],meta:displayDate(item[1]),done:item[3],reason:item.detail?.incomplete_reason,type:'Tagihan'})),items=[...agendaItems,...taskItems,...billItems],done=items.filter(item=>item.done).length,missed=items.filter(item=>!item.done).length,score=Math.max(0,Math.round((done*10-missed*2)/Math.max(1,items.length*10)*100));return shell(`<header class="simple-head"><h1>Riwayat Aktivitas</h1><p>Selesai, belum selesai, alasan, dan skor keluarga.</p></header><main class="content page-content"><section class="score-card"><span>Skor keluarga</span><b>${score}</b><small>${done} selesai · ${missed} perlu alasan/evaluasi</small></section><div class="list history-list">${items.length?items.map(item=>`<article><i class="item-icon">${item.done?'✓':'!'}</i><span><b class="${item.done?'':'danger-text'}">${safeText(item.title)}</b><small>${safeText(item.type)} · ${safeText(item.meta||'')}${item.done?' · selesai':` · belum selesai${item.reason?' · alasan: '+safeText(item.reason):' · alasan belum diisi'}`}</small></span></article>`).join(''):'<div class="empty-state">Belum ada aktivitas keluarga.</div>'}</div></main>`) }

function currentMember(){return (state.members||[]).find(member=>member.user_id===session?.user?.id)||{}}
function profile(){const members=state.members||[],familyName=state.family?.name||'Keluarga Saya',email=session?.user?.email||'Belum ada email',me=currentMember(),displayName=me.display_name||'Pengguna';return shell(`<header class="profile-head">${avatar()}<h1>${safeText(displayName)}</h1><p>${safeText(familyName)} · ${safeText(email)}</p><div class="profile-actions"><button data-action="avatar">Ganti Foto</button><button data-edit-profile>Ubah Nama</button></div></header><main class="content page-content"><section class="member-panel"><header><b>Anggota Keluarga</b><button data-share-code>＋ Undang</button></header>${members.length?members.map(m=>`<div class="member-row"><i>${safeText(m.display_name?.slice(0,1).toUpperCase()||'A')}</i><span><b>${safeText(m.display_name)}</b><small>${m.role==='owner'?'Pemilik keluarga':'Anggota keluarga'}</small></span></div>`).join(''):'<div class="empty-state">Belum ada anggota. Undang pasangan dengan kode keluarga.</div>'}<small class="invite-code">Kode keluarga: <b>${state.family?.invite_code||'-'}</b></small></section><div class="settings"><button data-enable-push>♢ <span>Notifikasi Push<small>${state.pushEnabled?'Aktif di perangkat ini':'Ketuk untuk aktifkan'}</small></span>›</button><button data-language-toggle>⚙ <span>Bahasa / Language<small>${state.lang==='en'?'English':'Bahasa Indonesia'}</small></span>›</button><button class="logout" data-action="logout">↪ <span>Keluar</span></button></div></main>`) }
function openProfileModal(){const old=$('#recordModal');if(old)old.remove();const me=currentMember(),modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Ubah Profil</b><button type="button" data-close-modal>×</button></header><input required name="displayName" placeholder="Nama kamu" value="${safeText(me.display_name||'')}"><input required name="familyName" placeholder="Nama keluarga" value="${safeText(state.family?.name||'')}" ${me.role==='owner'?'':'disabled'}>${me.role==='owner'?'':'<small>Nama keluarga hanya bisa diubah pemilik keluarga.</small>'}<button class="primary">Simpan Perubahan</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),displayName=d.get('displayName').trim(),familyName=d.get('familyName')?.trim();try{await sb(`/rest/v1/family_members?family_id=eq.${state.family.id}&user_id=eq.${session.user.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({display_name:displayName})});if(me.role==='owner'&&familyName&&familyName!==state.family.name){await sb(`/rest/v1/families?id=eq.${state.family.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({name:familyName})});state.family.name=familyName}const member=currentMember();if(member.display_name!==undefined)member.display_name=displayName;await loadFamily(true);modal.remove();render();toast('Profil diperbarui')}catch(error){toast(/permission|policy|row-level/i.test(error.message)?'Izin ubah profil belum aktif di Supabase':error.message)}}}
document.addEventListener('click',event=>{const filter=event.target.closest('[data-checklist-filter]');if(filter){event.preventDefault();state.homeChecklistFilter=filter.dataset.checklistFilter;save();render()}if(event.target.closest('[data-edit-profile]')){event.preventDefault();openProfileModal()}if(event.target.closest('[data-language-toggle]')){event.preventDefault();state.lang=state.lang==='en'?'id':'en';document.documentElement.lang=state.lang;save();render();toast(state.lang==='en'?'Language set to English':'Bahasa diubah ke Indonesia')}},true);

const setBusyWithQuietSync=setBusy;
setBusy=function(active,full=false){const loader=$('#appLoader');if(active){pendingRequests++;if(full)fullRequests++;if(pendingRequests===1&&full)busyTimer=setTimeout(()=>loader?.classList.add('show'),220);return}pendingRequests=Math.max(0,pendingRequests-1);if(full)fullRequests=Math.max(0,fullRequests-1);if(!pendingRequests){clearTimeout(busyTimer);loader?.classList.remove('show');syncIndicator.classList.remove('show')}};
const familyFingerprintWithEmergency=familyDataFingerprint;
familyDataFingerprint=function(){const base=JSON.parse(familyFingerprintWithEmergency());base.emergency=(state.emergencyRecords||[]).map(item=>[item.id,item.updated_at]);return JSON.stringify(base)};
const clearFamilyCacheWithEmergency=clearFamilyCache;
clearFamilyCache=function(){clearFamilyCacheWithEmergency();state.emergencyRecords=[]};
archivePage=function(){const docs=state.cloudDocs||[],folders=state.docFolders||[],activeFolder=state.archiveFolder?folders.find(f=>String(f.id)===String(state.archiveFolder)):null;const scopedDocs=activeFolder?docs.filter(x=>String(x.folder_id)===String(activeFolder.id)):docs.filter(x=>!x.folder_id);const countIn=id=>docs.filter(x=>String(x.folder_id)===String(id)).length;const folderGrid=!activeFolder?`<div class="folder-grid">${folders.map(f=>`<button type="button" class="folder-card" data-folder-open="${f.id}"><i>${icons.folder}</i><b>${safeText(f.name)}</b><small>${countIn(f.id)} file</small></button>`).join('')}<button type="button" class="folder-card folder-new" data-folder-new>${icons.plus}<b>Folder Baru</b></button></div>`:'';const folderHeader=activeFolder?`<div class="folder-path"><button type="button" data-folder-back>${icons.back} Arsip</button><b>${safeText(activeFolder.name)}</b><button type="button" class="folder-delete" data-folder-delete="${activeFolder.id}" aria-label="Hapus folder" title="Hapus folder">×</button></div>`:'';const sectionLabel=activeFolder?'':(folders.length?'<div class="section-label">TANPA FOLDER</div>':'');return shell(`${header(configs.archive)}<main class="content page-content"><section class="archive-tip"><b>Arsip pribadi keluarga</b><span>Unggah KTP, KK, STNK, sertifikat, bukti bayar, atau dokumen lainnya.</span></section><button class="add-card" data-archive-upload>${icons.plus}<span>Unggah Dokumen${activeFolder?` ke "${safeText(activeFolder.name)}"`:''}</span></button>${folderGrid}${folderHeader}${sectionLabel}<div class="list archive-list">${scopedDocs.length?scopedDocs.map(x=>`<article class="document-row"><i class="item-icon">${icons.archive}</i><span><b>${safeText(x.file_name)}</b><small>${safeText(x.category)} · ${Math.max(1,Math.round((x.file_size||0)/1024))} KB</small></span><div class="doc-actions"><button type="button" class="doc-icon-button" data-doc-preview="${x.id}" aria-label="Preview dokumen" title="Preview">${icons.glasses}</button><button type="button" class="doc-icon-button" data-doc-rename="${x.id}" aria-label="Rename arsip" title="Rename">${icons.pencil}</button><button type="button" class="doc-icon-button doc-icon-danger" data-doc-delete="${x.id}" aria-label="Hapus arsip" title="Hapus">${icons.trash}</button></div></article>`).join(''):`<div class="empty-state">${activeFolder?'Belum ada dokumen di folder ini.':'Belum ada arsip. Tambahkan dokumen penting keluarga di sini.'}</div>`}</div></main>`)};
document.addEventListener('click',event=>{const openBtn=event.target.closest('[data-folder-open]');if(openBtn){event.preventDefault();state.archiveFolder=openBtn.dataset.folderOpen;save();render();return}if(event.target.closest('[data-folder-back]')){event.preventDefault();state.archiveFolder=null;save();render();return}const newBtn=event.target.closest('[data-folder-new]');if(newBtn){event.preventDefault();if(!state.family){toast('Masuk dan buat keluarga terlebih dahulu');return}const name=prompt('Nama folder baru');if(!name||!name.trim())return;sb('/rest/v1/family_document_folders',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({family_id:state.family.id,name:name.trim(),created_by:session.user.id})}).then(saved=>{const row=saved?.[0];if(row)state.docFolders=[...(state.docFolders||[]),row].sort((a,b)=>a.name.localeCompare(b.name));save();render();toast('Folder dibuat')}).catch(error=>toast(/duplicate|unique/i.test(error.message)?'Nama folder itu sudah ada':error.message));return}const delBtn=event.target.closest('[data-folder-delete]');if(delBtn){event.preventDefault();if(!confirm('Hapus folder ini? Dokumen di dalamnya tidak ikut terhapus, cuma dipindah ke "Tanpa Folder".'))return;const id=delBtn.dataset.folderDelete;sb(`/rest/v1/family_document_folders?id=eq.${id}`,{method:'DELETE'}).then(()=>{state.docFolders=(state.docFolders||[]).filter(f=>String(f.id)!==String(id));(state.cloudDocs||[]).forEach(doc=>{if(String(doc.folder_id)===String(id))doc.folder_id=null});state.archiveFolder=null;save();render();toast('Folder dihapus')}).catch(error=>toast(error.message))}},true);
const actionBeforeFolder=action;action=function(a){if(a==='back'&&state.page==='archive'&&state.archiveFolder){state.archiveFolder=null;save();render();return}actionBeforeFolder(a)};
const openDocumentPreviewBeforeRename=openDocumentPreview;
openDocumentPreview=async function(doc){await openDocumentPreviewBeforeRename(doc);const footer=$('#documentPreview footer');if(footer&&!footer.querySelector('[data-doc-rename]'))footer.insertAdjacentHTML('afterbegin',`<button type="button" class="secondary doc-icon-button" data-doc-rename="${safeText(doc.id)}" aria-label="Rename arsip" title="Rename">${icons.pencil}</button>`)};
let familyLeafletMap=null;
function initFamilyMap(){const container=document.getElementById('familyMapCanvas');if(!container)return;if(typeof L==='undefined'){setTimeout(initFamilyMap,300);return}const places=(state.places||[]).filter(p=>(p.detail||{}).lat&&(p.detail||{}).lng);if(!places.length){familyLeafletMap=null;return}familyLeafletMap=L.map(container,{zoomControl:true,attributionControl:true});L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(familyLeafletMap);const markerById={};places.forEach(p=>{const d=p.detail||{},marker=L.marker([d.lat,d.lng]).addTo(familyLeafletMap);marker.bindPopup(`<b>${safeText(p.title||'Lokasi keluarga')}</b><br>${new Date(p.updated_at||p.created_at).toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'})}`);markerById[p.id]=marker});familyLeafletMap._markerById=markerById;if(places.length===1)familyLeafletMap.setView([places[0].detail.lat,places[0].detail.lng],15);else familyLeafletMap.fitBounds(L.featureGroup(Object.values(markerById)).getBounds().pad(0.25))}
document.addEventListener('click',event=>{const focusBtn=event.target.closest('[data-map-focus]');if(!focusBtn||!familyLeafletMap)return;const marker=familyLeafletMap._markerById?.[focusBtn.dataset.mapFocus];if(marker){familyLeafletMap.setView(marker.getLatLng(),16);marker.openPopup()}},true);
const renderBeforeMap=render;render=function(){renderBeforeMap();if(state.page==='map')requestAnimationFrame(initFamilyMap)};
function openDocumentRename(doc){$('#recordModal')?.remove();const folders=state.docFolders||[],modal=document.createElement('div');modal.id='recordModal';modal.className='record-modal';modal.innerHTML=`<form class="record-card"><header><b>Rename Arsip</b><button type="button" data-close-modal>×</button></header><input required name="fileName" placeholder="Nama dokumen" value="${safeText(doc.file_name)}"><select name="category"><option ${doc.category==='Dokumen'?'selected':''}>Dokumen</option><option ${doc.category==='KTP'?'selected':''}>KTP</option><option ${doc.category==='Kartu Keluarga'?'selected':''}>Kartu Keluarga</option><option ${doc.category==='STNK'?'selected':''}>STNK</option><option ${doc.category==='Sertifikat'?'selected':''}>Sertifikat</option><option ${doc.category==='Keuangan'?'selected':''}>Keuangan</option><option ${doc.category==='Kesehatan'?'selected':''}>Kesehatan</option><option ${doc.category==='Sekolah'?'selected':''}>Sekolah</option><option ${doc.category==='Lainnya'?'selected':''}>Lainnya</option></select><select name="folderId"><option value="" ${!doc.folder_id?'selected':''}>Tanpa Folder</option>${folders.map(f=>`<option value="${f.id}" ${String(doc.folder_id)===String(f.id)?'selected':''}>${safeText(f.name)}</option>`).join('')}</select><button class="primary">Simpan Nama</button></form>`;document.body.append(modal);$('form',modal).onsubmit=async e=>{e.preventDefault();const d=new FormData(e.target),file_name=d.get('fileName').trim(),category=d.get('category'),folder_id=d.get('folderId')||null;try{await sb(`/rest/v1/family_documents?id=eq.${doc.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({file_name,category,folder_id})});Object.assign(doc,{file_name,category,folder_id});save();await loadDocuments(true);modal.remove();$('#documentPreview')?.remove();render();toast('Nama arsip diperbarui')}catch(error){toast(/permission|policy|row-level/i.test(error.message)?'Izin rename arsip belum aktif. Jalankan SQL sinkronisasi terbaru.':error.message)}}}
async function deleteFamilyDocument(doc){if(!confirm(`Hapus "${doc.file_name}"? Tindakan ini tidak bisa dibatalkan.`))return;try{await fetch(`${SB_URL}/storage/v1/object/family-documents/${doc.file_path}`,{method:'DELETE',headers:{apikey:SB_KEY,Authorization:`Bearer ${session.access_token}`}});await sb(`/rest/v1/family_documents?id=eq.${doc.id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});state.cloudDocs=(state.cloudDocs||[]).filter(item=>String(item.id)!==String(doc.id));save();$('#documentPreview')?.remove();render();toast('Dokumen dihapus')}catch(error){toast(/permission|policy|row-level/i.test(error.message)?'Izin hapus arsip belum aktif. Jalankan SQL supabase-archive-delete.sql terlebih dahulu.':error.message)}}
document.addEventListener('click',event=>{const rename=event.target.closest('[data-doc-rename]');if(rename){event.preventDefault();event.stopImmediatePropagation();const doc=(state.cloudDocs||[]).find(item=>String(item.id)===String(rename.dataset.docRename));if(doc)openDocumentRename(doc);return}const del=event.target.closest('[data-doc-delete]');if(!del)return;event.preventDefault();event.stopImmediatePropagation();const id=del.dataset.docDelete||$('#documentPreview')?.dataset.documentId,doc=(state.cloudDocs||[]).find(item=>String(item.id)===String(id));if(doc)deleteFamilyDocument(doc)},true);
const familyFingerprintWithArchiveRename=familyDataFingerprint;
familyDataFingerprint=function(){const base=JSON.parse(familyFingerprintWithArchiveRename());base.documents=(state.cloudDocs||[]).map(item=>[item.id,item.file_name,item.category,item.folder_id]);base.folders=(state.docFolders||[]).map(item=>[item.id,item.name]);return JSON.stringify(base)};
bottom=function(){const labels=state.lang==='en'?{home:'Home',agenda:'Calendar',history:'History',profile:'Profile'}:{home:'Beranda',agenda:'Kalender',history:'Riwayat',profile:'Profil'};return `<nav class="bottom"><button data-tab="home" class="${state.tab==='home'?'active':''}">${icons.home}<span>${labels.home}</span></button><button data-tab="agenda" class="${state.tab==='agenda'?'active':''}">${icons.agenda}<span>${labels.agenda}</span></button><button data-tab="history" class="${state.tab==='history'?'active':''}">${icons.history}<span>${labels.history}</span></button><button data-tab="profile" class="${state.tab==='profile'?'active':''}">${icons.profile}<span>${labels.profile}</span></button></nav>`};
document.documentElement.lang=state.lang;
render();

// --- Arsip versi ringkas: klik data untuk preview, hanya pensil kecil untuk rename ---
archivePage=function(){const docs=state.cloudDocs||[],folders=state.docFolders||[],activeFolder=state.archiveFolder?folders.find(f=>String(f.id)===String(state.archiveFolder)):null;const scopedDocs=activeFolder?docs.filter(x=>String(x.folder_id)===String(activeFolder.id)):docs.filter(x=>!x.folder_id);const countIn=id=>docs.filter(x=>String(x.folder_id)===String(id)).length;const folderGrid=!activeFolder?`<div class="folder-grid">${folders.map(f=>`<button type="button" class="folder-card" data-folder-open="${f.id}"><i>${icons.folder}</i><b>${safeText(f.name)}</b><small>${countIn(f.id)} file</small></button>`).join('')}<button type="button" class="folder-card folder-new" data-folder-new>${icons.plus}<b>Folder Baru</b></button></div>`:'';const folderHeader=activeFolder?`<div class="folder-path"><button type="button" data-folder-back>${icons.back} Arsip</button><b>${safeText(activeFolder.name)}</b><button type="button" class="folder-delete" data-folder-delete="${activeFolder.id}" aria-label="Hapus folder" title="Hapus folder">×</button></div>`:'';const sectionLabel=activeFolder?'':(folders.length?'<div class="section-label">TANPA FOLDER</div>':'');return shell(`${header(configs.archive)}<main class="content page-content"><section class="archive-tip"><b>Arsip pribadi keluarga</b><span>Unggah KTP, KK, STNK, sertifikat, bukti bayar, atau dokumen lainnya.</span></section><button class="add-card" data-archive-upload>${icons.plus}<span>Unggah Dokumen${activeFolder?` ke "${safeText(activeFolder.name)}"`:''}</span></button>${folderGrid}${folderHeader}${sectionLabel}<div class="list archive-list compact-archive-list">${scopedDocs.length?scopedDocs.map(x=>`<article class="document-row"><button type="button" class="document-main" data-doc-preview="${x.id}" aria-label="Preview ${safeText(x.file_name)}"><i class="item-icon">${icons.archive}</i><span><b>${safeText(x.file_name)}</b><small>${safeText(x.category)} · ${Math.max(1,Math.round((x.file_size||0)/1024))} KB · ketuk untuk lihat</small></span></button><button type="button" class="doc-icon-button doc-rename-only" data-doc-rename="${x.id}" aria-label="Rename arsip" title="Rename">${icons.pencil}</button></article>`).join(''):`<div class="empty-state">${activeFolder?'Belum ada dokumen di folder ini.':'Belum ada arsip. Tambahkan dokumen penting keluarga di sini.'}</div>`}</div></main>`)};
if(typeof openDocumentPreviewBeforeRename==='function')openDocumentPreview=openDocumentPreviewBeforeRename;
const agendaStatusFinalKeepToday=agendaStatus;
agendaStatus=function(item){const detail=item.detail||{},diff=isoDaysFromNow(item.date),isToday=detail.repeat==='daily'||diff===0;if(item[3]&&isToday)return 'today';if(item[3])return 'done';if(diff<0)return 'missed';return agendaStatusFinalKeepToday(item)};
checklistItems=function(){const items=(state.agenda||[]).map((item,index)=>({item,index,status:agendaStatus(item)}));const filter=state.homeChecklistFilter||'today';if(filter==='today')return items.filter(entry=>['today','missed'].includes(entry.status));if(filter==='upcoming')return items.filter(entry=>entry.status==='upcoming'&&!entry.item[3]);if(filter==='done')return items.filter(entry=>entry.item[3]);return items};
render();

// --- Preview arsip final: modal hanya menampilkan Bagikan dan Download ---
const openDocumentPreviewArchiveFinal=openDocumentPreview;
openDocumentPreview=async function(doc){await openDocumentPreviewArchiveFinal(doc);$('#documentPreview [data-doc-rename]')?.remove();$('#documentPreview [data-doc-delete]')?.remove();$('#documentPreview [data-doc-full]')?.remove()};

// --- Badge internal app: chat belum dibaca, tugas, dan belanja ---
status=function(){return ''};
function badgeNumber(value){const count=Number(value)||0;return count>99?'99+':String(count)}
function chatReadKey(){return `portalChatRead:${session?.user?.id||'anon'}:${state.family?.id||'no-family'}`}
function chatLastRead(){return Number(localStorage.getItem(chatReadKey())||0)}
function markChatReadLocal(){if(!state.family)return;localStorage.setItem(chatReadKey(),String(Date.now()))}
function unreadChatCount(){const me=session?.user?.id,last=chatLastRead();return (state.messages||[]).filter(message=>message.sender_id!==me&&new Date(message.created_at).getTime()>last).length}
function appBadgeCount(page){if(page==='chat')return unreadChatCount();if(page==='quest')return (state.cloudTasks||[]).filter(task=>!task.completed).length;if(page==='shop')return (state.shopping||[]).filter(item=>!item[1]).length;return 0}
function renderInAppBadges(){['chat','quest','shop'].forEach(page=>{$$(`[data-page="${page}"]`).forEach(button=>{button.querySelector('.module-badge')?.remove();const count=appBadgeCount(page);if(count>0){const badge=document.createElement('span');badge.className='module-badge';badge.textContent=badgeNumber(count);badge.setAttribute('aria-label',`${count} belum selesai atau belum dibaca`);button.append(badge)}})})}
const renderBeforeInAppBadges=render;
render=function(){renderBeforeInAppBadges();if(state.page==='chat')markChatReadLocal();renderInAppBadges()};
render();
